import React, { useMemo, useState, useEffect } from 'react';
import { Service, ServiceStatus, User } from '../../types';
import Button from '../ui/Button';
// FIX: Added missing Icon imports
import { IconBellRinging, IconClipboardList, IconClock, IconUser, IconEngine, IconPhone, IconLink, IconCheck, IconShare, IconReceipt, IconMapPin } from '../ui/Icon';
import { getUncompletedDependencies } from '../../services/dependencyService';

interface AppointmentCardProps {
  service: Service;
  currentUser: User;
  allSubmissions: Service[];
  onAssign?: () => void;
  onStart?: () => void;
  onUpdate?: () => void;
  onClaim?: () => void;
  onDelete?: () => void;
  onNotify?: () => void;
  onShareOrder?: (service: Service) => void;
  isOverdue?: boolean;
  isToday?: boolean;
}

export const AppointmentCard: React.FC<AppointmentCardProps> = ({ service, currentUser, allSubmissions, onAssign, onStart, onUpdate, onClaim, onDelete, onNotify, onShareOrder, isOverdue, isToday }) => {

  const [showCompletionAnimation, setShowCompletionAnimation] = useState(false);

  useEffect(() => {
    if (service.status === ServiceStatus.Completed) {
      setShowCompletionAnimation(true);
      const timer = setTimeout(() => setShowCompletionAnimation(false), 1500); // Animation duration
      return () => clearTimeout(timer);
    }
  }, [service.status]);

  const uncompletedDependencies = useMemo(() => getUncompletedDependencies(service, allSubmissions), [service, allSubmissions]);
  const canStart = onStart && uncompletedDependencies.length === 0;

  const statusConfig = {
    [ServiceStatus.Completed]: { bg: 'bg-green-100', text: 'text-green-800', border: 'border-green-400' },
    [ServiceStatus.InProgress]: { bg: 'bg-purple-100', text: 'text-purple-800', border: 'border-purple-400' },
    [ServiceStatus.Assigned]: { bg: 'bg-blue-100', text: 'text-blue-800', border: 'border-blue-400' },
    [ServiceStatus.Queued]: { bg: 'bg-slate-100', text: 'text-slate-800', border: 'border-slate-400' },
    [ServiceStatus.Draft]: { bg: 'bg-yellow-100', text: 'text-yellow-800', border: 'border-yellow-400' },
  };

  const isCompleted = service.status === ServiceStatus.Completed;
  const currentStatusConfig = statusConfig[service.status] || statusConfig.Draft;
  const isAdminOrManager = currentUser.role === 'admin' || currentUser.role === 'manager';
  const isDraggable = isAdminOrManager && service.status === ServiceStatus.Queued;
  const canNotify = isAdminOrManager && onNotify && service.status !== ServiceStatus.Completed && service.status !== ServiceStatus.Draft;
  const canViewNotes = service.internalNotes && (isAdminOrManager || currentUser.username === service.assignedTo);

  const cardBorderColor = isOverdue ? 'border-red-400' : isToday ? 'border-brand-accent' : currentStatusConfig.border;

  const canShare = onShareOrder && navigator.share && service.status !== ServiceStatus.Draft;
  const canCall = service.mobileNumber && service.status !== ServiceStatus.Draft;
  const hasActions = onAssign || onStart || onUpdate || onClaim || onDelete;

  const hasLocation = !!(service.customerLatitude && service.customerLongitude);

  const serviceSummary = useMemo(() => {
    const services = service.serviceSelection.map(s => {
        if (s === 'Car Washing' && service.carWashDetails?.washType) {
            return service.carWashDetails.washType;
        }
         if (s === 'Car Care' && service.carCareDetails?.careType) {
            return service.carCareDetails.careType;
        }
        return s;
    });
    return services.join(', ') || 'N/A';
  }, [service.serviceSelection, service.carWashDetails, service.carCareDetails]);

  const renderAdminButtons = () => {
    return (
      <>
           {onDelete && <Button variant="danger" size="sm" onClick={onDelete}>Delete</Button>}
           {onUpdate && <Button variant="secondary" size="sm" onClick={onUpdate}>Edit</Button>}
           {service.status === ServiceStatus.Queued && onAssign && <Button onClick={onAssign} size="sm">Assign</Button>}
      </>
    );
  }

  const renderUserButtons = () => {
    const isAssignedToCurrentUser = service.assignedTo === currentUser.username;

    switch (service.status) {
      case ServiceStatus.Queued:
        return onClaim && <Button onClick={onClaim} size="sm">Claim Order</Button>;

      case ServiceStatus.Assigned:
        if (isAssignedToCurrentUser) {
          return (
            onStart && (
                <Button 
                  onClick={onStart} 
                  size="sm" 
                  disabled={!canStart}
                  title={!canStart ? `Blocked by prerequisite task(s): ${uncompletedDependencies.map(s => `#${s.appointmentId?.split('-').pop()}`).join(', ')}` : 'Start Order'}
                >
                  Start Order
                </Button>
            )
          );
        }
        return null;

      case ServiceStatus.InProgress:
        if (isAssignedToCurrentUser) {
           return onUpdate && <Button onClick={onUpdate} size="sm">Update Details</Button>;
        }
        return onUpdate && <Button onClick={onUpdate} size="sm">Update Details</Button>;

      case ServiceStatus.Completed:
           return <Button variant="ghost" disabled size="sm">Completed</Button>;
      default:
        return onUpdate && <Button variant="secondary" size="sm" onClick={onUpdate}>Edit</Button>;
    }
  }


  return (
    <div 
      className={`relative ${isCompleted ? 'bg-slate-100/50' : 'bg-white hover:shadow-md'} rounded-lg shadow-sm border-l-4 ${cardBorderColor} flex flex-col ${isDraggable ? 'cursor-grab' : ''} transition-all duration-300`}
      style={{ transition: 'background-color 500ms ease-in-out' }}
      draggable={isDraggable}
      onDragStart={isDraggable ? (e) => e.dataTransfer.setData('text/plain', service.submissionId) : undefined}
    >
      <div className="p-4 flex-grow">
         {canNotify && (
            <div className="absolute top-3 right-3 z-10">
                <Button 
                    size="sm" 
                    onClick={onNotify} 
                    className="p-2 h-9 w-9 rounded-full bg-slate-100 text-slate-500 hover:bg-brand-accent/20 hover:text-brand-accent transition-colors"
                    title="Send notification for this order"
                >
                    <IconBellRinging className="w-5 h-5" />
                </Button>
            </div>
        )}
        <div className="flex items-start justify-between">
            <div className="flex items-center space-x-3 flex-wrap gap-y-1">
              <h3 className="text-lg font-bold text-slate-800">{service.customerFirstName} {service.customerLastName}</h3>
              {service.appointmentId && <span className="text-sm font-mono text-brand-blue bg-blue-100 px-2 py-0.5 rounded-md">#{service.appointmentId.split('-').pop()}</span>}
              {isOverdue && <span className="text-xs font-semibold text-red-800 bg-red-100 px-2 py-0.5 rounded-full">Overdue</span>}
              {isToday && !isOverdue && <span className="text-xs font-semibold text-amber-800 bg-amber-100 px-2 py-0.5 rounded-full">Today</span>}
              {service.isAutoScheduled && (
                  <span title="This was automatically scheduled" className="text-xs font-semibold text-purple-800 bg-purple-100 px-2 py-0.5 rounded-full">Auto</span>
              )}
            </div>
             <span className={`px-3 py-1 text-xs font-semibold rounded-full flex-shrink-0 ml-2 flex items-center gap-1 ${currentStatusConfig.bg} ${currentStatusConfig.text}`}>
                {showCompletionAnimation && <IconCheck className="w-4 h-4 animate-check" />}
                <span>{service.status}</span>
            </span>
        </div>

        <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-2 text-sm text-slate-600">
            <div className="flex items-center">
                <IconEngine className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>{service.carBrandModel} ({service.carNumber})</span>
            </div>
            <div className="flex items-center">
                <IconUser className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>Assigned to: <strong className="font-semibold">{service.assignedTo || 'Unassigned'}</strong></span>
            </div>
            {service.streetAddress && (
                <div className="flex items-start sm:col-span-2">
                    <IconMapPin className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0 mt-0.5" />
                    <span>{service.streetAddress}</span>
                </div>
            )}
            <div className="flex items-start sm:col-span-2">
                <IconClipboardList className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0 mt-0.5" />
                <span>Services: <strong className="font-semibold">{serviceSummary}</strong></span>
            </div>
            <div className="flex items-center">
                <IconClock className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>Scheduled: <strong className="font-semibold">{service.scheduledDate ? new Date(service.scheduledDate).toLocaleDateString() : 'N/A'} at {service.scheduledTime || 'N/A'}</strong></span>
            </div>
             <div className="flex items-center">
                <IconReceipt className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>Value: <strong className="font-bold text-slate-800">₹{service.grandTotal.toFixed(2)}</strong></span>
            </div>
        </div>

        {canViewNotes && (
            <div className="mt-3 p-2.5 bg-yellow-50 border-l-4 border-yellow-300 rounded-r-md flex items-start space-x-3">
                <IconClipboardList className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                <div>
                    <p className="text-xs font-bold text-yellow-800 uppercase tracking-wide">Internal Note</p>
                    <p className="text-sm text-yellow-900 whitespace-pre-wrap">{service.internalNotes}</p>
                </div>
            </div>
        )}
        {uncompletedDependencies.length > 0 && (
            <div className="mt-3 p-2.5 bg-amber-50 border-l-4 border-amber-300 rounded-r-md flex items-start space-x-3">
                <IconLink className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
                <div>
                    <p className="text-xs font-bold text-amber-800 uppercase tracking-wide">Blocked by Prerequisite</p>
                    <p className="text-sm text-amber-900">
                        Cannot be started until task(s) {uncompletedDependencies.map(dep => ` #${dep.appointmentId?.split('-').pop()}`).join(', ')} are complete.
                    </p>
                </div>
            </div>
        )}
      </div>

      {(hasActions || canShare || canCall || hasLocation) && (
         <div className="px-4 py-3 bg-slate-50/70 border-t border-slate-200">
            <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center space-x-2">
                    {hasLocation && (
                         <a href={`https://www.google.com/maps/search/?api=1&query=${service.customerLatitude},${service.customerLongitude}`} target="_blank" rel="noopener noreferrer" aria-label="Navigate to customer">
                            <Button variant="secondary" size="sm" title="Navigate" className="px-2">
                                <IconMapPin className="w-4 h-4 mr-1.5" />
                                Map
                            </Button>
                         </a>
                    )}
                    {canShare && (
                        <Button variant="secondary" size="sm" onClick={() => onShareOrder!(service)} title="Share Order Details" className="px-2">
                            <IconShare className="w-4 h-4 mr-1.5" />
                            Share
                        </Button>
                    )}
                    {canCall && (
                       <a href={`tel:${service.mobileNumber}`} aria-label={`Call ${service.customerFirstName}`}>
                         <Button variant="secondary" size="sm" title="Call Customer" className="px-2">
                           <IconPhone className="w-4 h-4 mr-1.5" />
                           Call
                         </Button>
                       </a>
                    )}
                </div>
                <div className="flex items-center justify-end space-x-2">
                    {isAdminOrManager ? renderAdminButtons() : renderUserButtons()}
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default AppointmentCard;

