import React, { useState } from 'react';
import { PricingConfig, PriceMatrix, VehicleCategoryTag } from '../../types';
import { VEHICLE_CATEGORY_TAGS, WASH_TYPES, CAR_CARE_TYPES, DYNAMIC_ADDON_NAMES } from '../../constants';
import Card from '../ui/Card';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { IconDeviceFloppy, IconRefresh } from '../ui/Icon';

interface Props {
  pricingConfig: PricingConfig;
  onUpdatePricing: (config: PricingConfig) => void;
}

const MatrixEditor: React.FC<{
    title: string;
    rows: string[];
    matrix: PriceMatrix;
    onChange: (updatedMatrix: PriceMatrix) => void;
}> = ({ title, rows, matrix, onChange }) => {

    // Helper to safely get value
    const getValue = (row: string, col: string, field: 'price' | 'mrp') => {
        return matrix[row]?.[col]?.[field] ?? 0;
    };

    const handleCellChange = (row: string, col: string, field: 'price' | 'mrp', value: string) => {
        const numValue = parseFloat(value) || 0;
        const newMatrix = { ...matrix };

        if (!newMatrix[row]) newMatrix[row] = {};
        if (!newMatrix[row][col]) newMatrix[row][col] = { price: 0, mrp: 0 };

        newMatrix[row][col] = {
            ...newMatrix[row][col],
            [field]: numValue
        };

        onChange(newMatrix);
    };

    return (
        <Card title={title} className="overflow-hidden">
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-slate-200 border-collapse">
                    <thead className="bg-slate-50">
                        <tr>
                            <th className="px-3 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider sticky left-0 bg-slate-50 z-10 border-b">
                                Service / Variant
                            </th>
                            {VEHICLE_CATEGORY_TAGS.map(tag => (
                                <th key={tag} className="px-2 py-3 text-center text-xs font-bold text-slate-500 uppercase tracking-wider min-w-[140px] border-l border-slate-200">
                                    {tag}
                                </th>
                            ))}
                        </tr>
                    </thead>
