  const [vehicleData, setVehicleData] = useState<Record<string, string[]>>(CAR_BRANDS);
  const [tyreData, setTyreData] = useState<TyreData>({ brands: TIRE_BRANDS, models: [], sizes: [] });
  const [pricingConfig, setPricingConfig] = useState<PricingConfig>(DEFAULT_PRICING_CONFIG);

  const [editingService, setEditingService] = useState<Service | null>(null);
  const [editingTemplate, setEditingTemplate] = useState<ServiceTemplate | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [printingService, setPrintingService] = useState<Service | null>(null);
  const [summarizingService, setSummarizingService] = useState<Service | null>(null);
  const [deletingService, setDeletingService] = useState<Service | null>(null);
  const [sharingService, setSharingService] = useState<Service | null>(null);

  const [syncStatus, setSyncStatus] = useState<SyncStatus>('OFFLINE');
  const [syncError, setSyncError] = useState<string | null>(null);
  const [logoHasError, setLogoHasError] = useState(false);

  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const isInitialLoad = useRef(true);

  const [isSidebarMinimized, setIsSidebarMinimized] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [isNotificationHistoryOpen, setIsNotificationHistoryOpen] = useState(false);
  const locationWatcherIdRef = useRef<number | null>(null);
  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
  const [publicService, setPublicService] = useState<{ data: any } | null>(null);

  const loadAndMergeData = useCallback(async (isInitial: boolean = false) => {
    if (isInitial) {
        setAppIsLoading(true);
    }
    setSyncError(null);
    setSyncStatus('SYNCING');

    const persistedSettings = {
        googleSheetsUrl: PERMANENT_SHEET_URL,
        googleDriveUploadUrl: PERMANENT_DRIVE_URL,
        customLogoUrl: localStorage.getItem('customLogoUrl') || '',
        retentionKpiTargets: JSON.parse(localStorage.getItem('retentionKpiTargets') || 'null') || defaultKpiTargets,
    };

    try {
        const cloudData = await cloudDataService.loadAppData(persistedSettings);
        let usersToSet = cloudData.users;

        if (usersToSet.length === 0 && cloudData.submissions.length === 0) {
            console.log("No users or data found, assuming first-time setup. Creating default admin.");
            const defaultAdmin: User = { 
                username: 'admin', password: 'admin@123', role: 'admin', 
                notificationPreferences: defaultNotificationPrefs, 
                permissions: authService.getDefaultPermissionsForRole('admin'),
                attendanceStatus: 'CHECKED_OUT',
                attendanceHistory: [],
            };
            usersToSet = [defaultAdmin];
            cloudDataService.saveRecord('Users', defaultAdmin, PERMANENT_SHEET_URL);
        }

        usersToSet = usersToSet.map(user => {
            const finalUser = { ...user };
            let needsSave = false;
            if (!finalUser.notificationPreferences) {
                 finalUser.notificationPreferences = mergeWithDefaultPrefs();
                 needsSave = true;
            }
            if ((finalUser.role as any) === 'user') {
                finalUser.role = 'agent';
                needsSave = true;
            }
            if (!finalUser.attendanceStatus) {
                finalUser.attendanceStatus = 'CHECKED_OUT';
                needsSave = true;
            }
            if (!finalUser.attendanceHistory) {
                finalUser.attendanceHistory = [];
                needsSave = true;
            }
            if (!finalUser.permissions || finalUser.permissions.length === 0) {
                console.log(`Migrating permissions for user ${finalUser.username} with role ${finalUser.role}`);
                finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role);
                needsSave = true;
            }
            if (needsSave) {
                 cloudDataService.saveRecord('Users', finalUser, PERMANENT_SHEET_URL);
            }
            return finalUser;
        });


        const localSubmissionsJson = localStorage.getItem('service_app_submissions');
        const rawLocalSubmissions: Service[] = localSubmissionsJson ? JSON.parse(localSubmissionsJson) : [];

        // Apply robust cleaning to BOTH local and cloud submissions before merging
        const cleanedLocalSubmissions = cleanSubmissionsArray(rawLocalSubmissions);
        const cleanedCloudSubmissions = cleanSubmissionsArray(cloudData.submissions);

        const mergedSubmissions = mergeSubmissions(cleanedCloudSubmissions, cleanedLocalSubmissions);

        setSubmissions(mergedSubmissions);
        setUsers(usersToSet);
        setSettings({
            ...cloudData.settings,
            googleSheetsUrl: PERMANENT_SHEET_URL,
            googleDriveUploadUrl: PERMANENT_DRIVE_URL,
            retentionKpiTargets: cloudData.settings.retentionKpiTargets || defaultKpiTargets,
        });
        setSubscriptionPlans(cloudData.subscriptionPlans || []);
        setUserSubscriptions(cloudData.userSubscriptions || []);
        setServiceTemplates(cloudData.serviceTemplates.length > 0 ? cloudData.serviceTemplates : DEFAULT_SERVICE_TEMPLATES);
        setServiceRequests(cloudData.serviceRequests || []);
        setNotifications(cloudData.notifications || []);
        setLocationHistory(cloudData.locationHistory || []);
        setMiscSpends(cloudData.miscSpends || []);
        setBookkeeping(cloudData.bookkeeping || []);
        setProfitLossData(cloudData.profitLoss || []);
        setVehicleData(cloudData.vehicleData || CAR_BRANDS);
        setTyreData(cloudData.tyreData || { brands: TIRE_BRANDS, models: [], sizes: [] });
        setPricingConfig(cloudData.pricingConfig || DEFAULT_PRICING_CONFIG);

        if(cloudData.serviceTemplates.length === 0) {
            DEFAULT_SERVICE_TEMPLATES.forEach(t => cloudDataService.saveRecord('ServiceTemplates', t, PERMANENT_SHEET_URL));
        }
         if(!cloudData.settings.retentionKpiTargets) {
            cloudDataService.saveRecord('Settings', { ...settings, retentionKpiTargets: defaultKpiTargets, googleSheetsUrl: PERMANENT_SHEET_URL}, PERMANENT_SHEET_URL);
        }

        setSyncStatus('SYNCED');

    } catch (e) {
        console.error("Failed to load data from cloud, attempting to load from local storage.", e);
        setSyncStatus('OFFLINE'); // Explicitly set to OFFLINE rather than ERROR so user knows they are on local data
        const errorMessage = e instanceof Error ? e.message : "Could not load data from cloud. Check settings and connection.";
        setSyncError(errorMessage);

        const localSubmissionsJson = localStorage.getItem('service_app_submissions');
        const rawLocalSubmissions: Service[] = localSubmissionsJson ? JSON.parse(localSubmissionsJson) : [];
        const cleanedLocalSubmissions = cleanSubmissionsArray(rawLocalSubmissions);
        setSubmissions(cleanedLocalSubmissions);

        const localUsers: User[] = JSON.parse(localStorage.getItem('service_app_users') || '[]');
        const usersWithDefaults = localUsers.map(u => {
            let finalUser = {...u, notificationPreferences: mergeWithDefaultPrefs(u.notificationPreferences) };
             if ((finalUser.role as any) === 'user') {
                finalUser.role = 'agent';
            }
             if (!finalUser.attendanceStatus) {
                finalUser.attendanceStatus = 'CHECKED_OUT';
            }
            if(!finalUser.attendanceHistory) {
                finalUser.attendanceHistory = [];
            }
            if (!finalUser.permissions || finalUser.permissions.length === 0) {
                 finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role);
            }
            return finalUser;
        });

        if (usersWithDefaults.length === 0) {
            usersWithDefaults.push({
                username:"admin",
                password:"admin@123",
                role:"admin",
                permissions: authService.getDefaultPermissionsForRole('admin'),
                notificationPreferences: defaultNotificationPrefs,
                attendanceStatus: 'CHECKED_OUT',
                attendanceHistory: []
            });
        }
        setUsers(usersWithDefaults);
        setSettings(persistedSettings);
        setSubscriptionPlans(JSON.parse(localStorage.getItem('service_app_subscription_plans') || '[]'));
        setUserSubscriptions(JSON.parse(localStorage.getItem('service_app_user_subscriptions') || '[]'));
        setServiceTemplates(JSON.parse(localStorage.getItem('service_app_service_templates') || JSON.stringify(DEFAULT_SERVICE_TEMPLATES)));
        setServiceRequests(JSON.parse(localStorage.getItem('service_app_service_requests') || '[]'));
        setNotifications(JSON.parse(localStorage.getItem('service_app_notifications') || '[]'));
        setLocationHistory(JSON.parse(localStorage.getItem('service_app_location_history') || '[]'));
        setMiscSpends(JSON.parse(localStorage.getItem('service_app_misc_spends') || '[]'));
        setBookkeeping(JSON.parse(localStorage.getItem('service_app_bookkeeping') || '[]'));
        setProfitLossData(JSON.parse(localStorage.getItem('service_app_profit_loss') || '[]'));
        setVehicleData(JSON.parse(localStorage.getItem('service_app_vehicle_data') || JSON.stringify(CAR_BRANDS)));
        setTyreData(JSON.parse(localStorage.getItem('service_app_tyre_data') || JSON.stringify({ brands: TIRE_BRANDS, models: [], sizes: [] })));
        setPricingConfig(JSON.parse(localStorage.getItem('service_app_pricing_config') || JSON.stringify(DEFAULT_PRICING_CONFIG)));
    } finally {
        if (isInitial) {
          setAppIsLoading(false);
        }
        isInitialLoad.current = false;
    }
  }, []);

  useEffect(() => {
    const hash = window.location.hash;
    if (hash.startsWith('#service=')) {
      setAppIsLoading(true);
      try {
        const encodedData = decodeURIComponent(hash.substring('#service='.length));
        const jsonString = atob(encodedData);
        const serviceData = JSON.parse(jsonString);

        setPublicService({ data: serviceData });
        setAppIsLoading(false);
      } catch (e) {
        console.error("Failed to parse shared service data:", e);
        window.location.hash = '';
        cloudDataService.init({ onSyncStatusChange: setSyncStatus, onSyncError: setSyncError }, settings.googleSheetsUrl);
        loadAndMergeData(true);
      }
    } else {
      cloudDataService.init({
          onSyncStatusChange: setSyncStatus,
          onSyncError: setSyncError,
      }, settings.googleSheetsUrl);
      loadAndMergeData(true);
    }
  }, [loadAndMergeData, settings.googleSheetsUrl]);

  // Timed reminders for upcoming & overdue services
  useEffect(() => {
    const checkServiceReminders = () => {
        const now = new Date();
        const newNotifications: AppNotification[] = [];

        submissions.forEach(service => {
            if (service.status !== ServiceStatus.Assigned && service.status !== ServiceStatus.InProgress) return;
            // Skip deleted items for notifications
            if (service.isDeleted) return;

            const scheduledDateTime = parseServiceDateTime(service);
            if (!scheduledDateTime) return;

            if (scheduledDateTime > now) {
                // --- UPCOMING REMINDER LOGIC ---
                const minutesUntil = (scheduledDateTime.getTime() - now.getTime()) / 60000;
                const targetUser = users.find(u => u.username === service.assignedTo);
                if (!targetUser) return;

                const prefs = targetUser.notificationPreferences || defaultNotificationPrefs;

                const has60MinReminder = notifications.some(n => n.serviceId === service.submissionId && n.type === 'reminder-60min');
                if (minutesUntil > 59 && minutesUntil <= 60 && !has60MinReminder) {
                    const message = `Reminder: Service for ${service.customerFirstName} is due in 1 hour.`;
                    const notif: AppNotification = {
                        id: `notif_rem60_${service.submissionId}`, userId: service.assignedTo!, serviceId: service.submissionId, message,
                        timestamp: new Date().toISOString(), isRead: false, type: 'reminder-60min'
                    };
                    newNotifications.push(notif);
                    if(prefs.enabled.reminder) {
                        playNotificationAlert(prefs);
                        if (targetUser.pushSubscription) sendPushNotification(targetUser.pushSubscription, "Upcoming Service", message, prefs);
                    }
                }

                const has30MinReminder = notifications.some(n => n.serviceId === service.submissionId && n.type === 'reminder-30min');
                if (minutesUntil > 29 && minutesUntil <= 30 && !has30MinReminder) {
                     const message = `Reminder: Service for ${service.customerFirstName} is due in 30 minutes.`;
                     const notif: AppNotification = {
                        id: `notif_rem30_${service.submissionId}`, userId: service.assignedTo!, serviceId: service.submissionId, message,
                        timestamp: new Date().toISOString(), isRead: false, type: 'reminder-30min'
                    };
                    newNotifications.push(notif);
                    if(prefs.enabled.reminder) {
                        playNotificationAlert(prefs);
                        if (targetUser.pushSubscription) sendPushNotification(targetUser.pushSubscription, "Upcoming Service", message, prefs);
                    }
                }
            } else {
                // --- OVERDUE REMINDER LOGIC ---
                const minutesSince = (now.getTime() - scheduledDateTime.getTime()) / 60000;

                if (minutesSince > 60) { // Over 1 hour late
                    const lastOverdueNotification = notifications
                        .filter(n => n.serviceId === service.submissionId && n.type === 'overdue-alert')
                        .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

                    let shouldSend = true;
                    if (lastOverdueNotification) {
                        const minutesSinceLastAlert = (now.getTime() - new Date(lastOverdueNotification.timestamp).getTime()) / 60000;
                        if (minutesSinceLastAlert < 60) { // Don't send more than once per hour
                            shouldSend = false;
                        }
                    }

                    if (shouldSend) {
                        const message = `OVERDUE: Service for ${service.customerFirstName} is more than 1 hour past its scheduled time.`;
                        const usersToNotify = users.filter(u => u.username === service.assignedTo || u.role === 'admin' || u.role === 'manager');

                        usersToNotify.forEach(user => {
                            const prefs = user.notificationPreferences || defaultNotificationPrefs;
                            if (prefs.enabled.overdue) {
                                 const notif: AppNotification = {
                                    id: `notif_overdue_${service.submissionId}_${user.username}_${Date.now()}`, userId: user.username, serviceId: service.submissionId,
                                    message, timestamp: new Date().toISOString(), isRead: false, type: 'overdue-alert'
                                };
                                newNotifications.push(notif);
                                playNotificationAlert(prefs);
                                if (user.pushSubscription) sendPushNotification(user.pushSubscription, "Service Overdue", message, prefs);
                            }
                        });
                    }
                }
            }
        });

        if (newNotifications.length > 0) {
            setNotifications(prev => [...prev, ...newNotifications]);
            newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
        }
    };

    if (currentUser) {
       const intervalId = setInterval(checkServiceReminders, 60 * 1000);
       return () => clearInterval(intervalId);
    }
  }, [submissions, notifications, currentUser, users, settings.googleSheetsUrl]);

  // Local storage backup effect - WRAPPED IN SAFE HELPER AND TRUNCATED
  const saveToLocalStorage = (key: string, data: any) => {
    try {
      localStorage.setItem(key, JSON.stringify(data));
    } catch (error) {
      console.warn(`Failed to save ${key} to localStorage:`, error);
    }
  };

  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_submissions', submissions); }, [submissions]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_users', users); }, [users]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_subscription_plans', subscriptionPlans); }, [subscriptionPlans]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_user_subscriptions', userSubscriptions); }, [userSubscriptions]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_service_templates', serviceTemplates); }, [serviceTemplates]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_service_requests', serviceRequests); }, [serviceRequests]);

  // Truncate potentially large arrays for local storage to avoid QuotaExceededError
  useEffect(() => { 
      if (!isInitialLoad.current) {
          // Keep only the last 200 notifications
          saveToLocalStorage('service_app_notifications', notifications.slice(-200)); 
      }
  }, [notifications]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          // Keep only the last 500 location points
          saveToLocalStorage('service_app_location_history', locationHistory.slice(-500)); 
      }
  }, [locationHistory]);

  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_misc_spends', miscSpends); }, [miscSpends]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_bookkeeping', bookkeeping); }, [bookkeeping]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_profit_loss', profitLossData); }, [profitLossData]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_vehicle_data', vehicleData); }, [vehicleData]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_tyre_data', tyreData); }, [tyreData]);
  useEffect(() => { if (!isInitialLoad.current) saveToLocalStorage('service_app_pricing_config', pricingConfig); }, [pricingConfig]);

  useEffect(() => {
    if (isInitialLoad.current) return;
    try {
        localStorage.setItem('customLogoUrl', settings.customLogoUrl);
        if(settings.retentionKpiTargets) {
          localStorage.setItem('retentionKpiTargets', JSON.stringify(settings.retentionKpiTargets));
        }
    } catch (e) { console.warn("Failed to save settings to localStorage", e); }
  }, [settings]);


  // Effect for real-time location tracking based on attendance status
  useEffect(() => {
    if (!currentUser || currentUser.attendanceStatus !== 'CHECKED_IN') {
      if (locationWatcherIdRef.current !== null) {
        console.log(`Clearing location watcher for ${currentUser?.username} due to checkout or role.`);
        navigator.geolocation.clearWatch(locationWatcherIdRef.current);
        locationWatcherIdRef.current = null;
      }
      return;
    }

    if ('geolocation' in navigator) {
      console.log(`Starting location tracking for checked-in user: ${currentUser.username}`);

      const successCallback = (position: GeolocationPosition) => {
        const { latitude, longitude } = position.coords;
        console.log(`Location update for ${currentUser.username}: ${latitude}, ${longitude}`);

        const activeService = submissions.find(
            s => s.assignedTo === currentUser.username && s.status === ServiceStatus.InProgress
        );

        const newHistoryRecord: LocationHistory = {
            historyId: `hist_${Date.now()}`,
            userId: currentUser.username,
            latitude,
            longitude,
            timestamp: new Date().toISOString(),
            relatedServiceId: activeService?.submissionId,
        };

        setLocationHistory(currentHistory => [...currentHistory, newHistoryRecord]);
        cloudDataService.saveRecord('LocationHistory', newHistoryRecord, settings.googleSheetsUrl);

        setUsers(currentUsers => { // Use functional update for safety
            const updatedUsers = currentUsers.map(u =>
              u.username === currentUser.username
                ? { ...u, latitude, longitude, lastLocationUpdate: new Date().toISOString() }
                : u
            );
            const userToSave = updatedUsers.find(u => u.username === currentUser.username);
            if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
            return updatedUsers;
        });
      };

      const errorCallback = (GeolocationPositionError) => {
        console.error(`Geolocation error for ${currentUser.username}: ${GeolocationPositionError.message} (Code: ${GeolocationPositionError.code})`);
      };

      const watchOptions: PositionOptions = {
        enableHighAccuracy: true,
        timeout: 15000,
        maximumAge: 0,
      };

      locationWatcherIdRef.current = navigator.geolocation.watchPosition(
        successCallback, errorCallback, watchOptions
      );

    } else {
      console.warn("Geolocation is not supported by this browser.");
    }

    return () => {
      if (locationWatcherIdRef.current !== null) {
        navigator.geolocation.clearWatch(locationWatcherIdRef.current);
        locationWatcherIdRef.current = null;
      }
    };
  }, [currentUser, submissions, settings.googleSheetsUrl]); // Re-run effect if currentUser changes (e.g., attendance status)

  // Effect for auto-refreshing data for admins (for live map)
  useEffect(() => {
      const isAdminOrManager = currentUser?.permissions.includes(Permission.CAN_VIEW_LIVE_MAP);
      if (isAdminOrManager && view === 'LIVE_MAP') {
          console.log("Admin/Manager is on the live map, starting auto-refresh.");
          const intervalId = setInterval(() => {
              if (!isManualRefreshing) {
                  console.log("Auto-refreshing data for admin map...");
                  loadAndMergeData(false);
              }
          }, 30000); // Refresh every 30 seconds

          return () => {
              console.log("Stopping auto-refresh.");
              clearInterval(intervalId);
          };
      }
  }, [currentUser, view, isManualRefreshing, loadAndMergeData]);


  const handleManualRefresh = async () => {
    if (isManualRefreshing) return;
    setIsManualRefreshing(true);
    await loadAndMergeData(false);
    setIsManualRefreshing(false);
  };

  const handleLoginAttempt = useCallback((username: string, password?: string) => {
    setLoginError('');
    const validatedUser = authService.validateLogin(username, password, users);
    if (validatedUser) {
        try {
            const userFromFullList = users.find(u => u.username === validatedUser.username);
            const finalUser = {
                ...(userFromFullList || validatedUser),
                notificationPreferences: mergeWithDefaultPrefs(userFromFullList?.notificationPreferences)
            };
            localStorage.setItem('service_app_current_user', JSON.stringify(finalUser));
            setCurrentUser(finalUser);
            setView('DASHBOARD');
        } catch (error) {
            console.error("Failed to save user session:", error);
            setLoginError("A problem occurred while trying to log you in. Please try again.");
        }
    } else {
        setLoginError('Invalid username or password.');
    }
  }, [users]);

  const handleLogout = () => {
    // Automatically check out the user on logout if they were checked in
    if (currentUser?.attendanceStatus === 'CHECKED_IN') {
        handleUpdateAttendanceStatus(currentUser.username, 'CHECKED_OUT');
    }
    setCurrentUser(null);
    localStorage.removeItem('service_app_current_user');
    setSyncError(null);
    setView('DASHBOARD');
  };

  const handleEditService = (service: Service | null) => {
    setEditingService(service);
    setView('FORM');
    setIsMobileMenuOpen(false);
  };

  const handleNavigate = (view: AppView) => {
    setView(view);
    setIsMobileMenuOpen(false);
  }

  const handleEditTemplate = (template: ServiceTemplate) => {
    setEditingTemplate(template);
    setView('SERVICE_TEMPLATE_EDITOR');
    setIsMobileMenuOpen(false);
  };

  const handleSaveDraftFromChatbot = (serviceDataFromAi: Partial<Service>) => {
    const submissionId = `SUB-${Date.now()}`;

    const newService: Service = {
        ...createDefaultServiceState(), // Get a full default service object
        ...serviceDataFromAi, // Overwrite defaults with AI data
        submissionId: submissionId,
        appointmentId: submissionId,
        timestamp: new Date().toISOString(),
        status: ServiceStatus.Draft, // Always save as a draft for review
        submittedBy: `AI Assistant via ${currentUser?.username}`,
    };
    setSubmissions(prev => [...prev, newService]);
    cloudDataService.saveRecord('Submissions', newService, settings.googleSheetsUrl);
  };

  const handleCreateFollowUp = (customer: Customer, serviceSelection: string[]) => {
    const newService = createDefaultServiceState();

    const prefilledService: Service = {
        ...newService,
        customerFirstName: customer.firstName,
        customerLastName: customer.lastName,
        mobileNumber: customer.mobileNumber,
        carNumber: customer.carNumber,
        carBrandModel: customer.carBrandModel,
        streetAddress: customer.streetAddress,
        customerEmail: customer.customerEmail,
        serviceSelection: serviceSelection,
        status: ServiceStatus.Draft, // Start as a draft for review
        isFollowUp: true,
    };
    handleEditService(prefilledService);
  };

  const handleCompleteOrder = (service: Service) => {
    const isUpdating = submissions.some(s => s.submissionId === service.submissionId);
    let serviceToSave: Service;
    let wasSubscriptionUpdated = false;
    let finalUserSubscriptions = userSubscriptions;
    let serviceWithCleanedQuantities = { ...service };

    let newNotifications: AppNotification[] = [];

    const canAdminEdit = currentUser?.permissions.includes(Permission.CAN_EDIT_ANY_ORDER);

    if (isUpdating) {
        const originalService = submissions.find(s => s.submissionId === service.submissionId)!;

        const finalStatus = canAdminEdit 
            ? service.status
            : ServiceStatus.Completed;

        serviceToSave = {
            ...serviceWithCleanedQuantities, 
            status: finalStatus,
            timestamp: new Date().toISOString(),
            submittedBy: originalService.submittedBy || currentUser?.username,
        };

        const wasCompleted = originalService.status === ServiceStatus.Completed;
        const isNowCompleted = finalStatus === ServiceStatus.Completed;

        if (!wasCompleted && isNowCompleted) {
            // Add income entry to bookkeeping
            const newIncomeEntry: BookkeepingEntry = {
                id: `bk_inc_${serviceToSave.submissionId}`,
                timestamp: new Date().toISOString(),
                type: BookkeepingEntryType.Income,
                description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`,
                amount: serviceToSave.grandTotal,
                relatedId: serviceToSave.submissionId,
                recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system',
            };
            setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
            cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);

            if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
                const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
                if (userSubIndex > -1) {
                    const updatedSubs = [...userSubscriptions];
                    const subToUpdate = {...updatedSubs[userSubIndex]};
                    const washesUsed = serviceToSave.carWashDetails ? 1 : (serviceToSave.carwashQuantity || 1);
                    subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - washesUsed);
                    updatedSubs[userSubIndex] = subToUpdate;
                    finalUserSubscriptions = updatedSubs;
                    wasSubscriptionUpdated = true;
                    cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
                }
            }
            if (serviceToSave.assignedTo) {
                 const message = `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`;
                 newNotifications.push({
                    id: `notif_complete_${serviceToSave.submissionId}`,
                    userId: serviceToSave.assignedTo,
                    serviceId: serviceToSave.submissionId,
                    message,
                    timestamp: new Date().toISOString(),
                    isRead: false,
                    type: 'completed'
                });
            }
            sendCustomerEmailNotification(serviceToSave);
        } else if (wasCompleted && !isNowCompleted) {
            // Remove income entry from bookkeeping
            setBookkeeping(prev => prev.filter(b => b.relatedId !== serviceToSave.submissionId));
            cloudDataService.deleteRecord('Bookkeeping', `bk_inc_${serviceToSave.submissionId}`, settings.googleSheetsUrl);
        }

    } else {
        serviceToSave = {
            ...serviceWithCleanedQuantities,
            status: ServiceStatus.Completed,
            assignedTo: currentUser?.username,
            submittedBy: currentUser?.username,
            timestamp: new Date().toISOString(),
        };

        const newIncomeEntry: BookkeepingEntry = {
            id: `bk_inc_${serviceToSave.submissionId}`,
            timestamp: new Date().toISOString(),
            type: BookkeepingEntryType.Income,
            description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`,
            amount: serviceToSave.grandTotal,
            relatedId: serviceToSave.submissionId,
            recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system',
        };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);

        if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
             const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
            if (userSubIndex > -1) {
                const updatedSubs = [...userSubscriptions];
                const subToUpdate = {...updatedSubs[userSubIndex]};
                const washesUsed = serviceToSave.carWashDetails ? 1 : (serviceToSave.carwashQuantity || 1);
                subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - washesUsed);
                updatedSubs[userSubIndex] = subToUpdate;
                finalUserSubscriptions = updatedSubs;
                wasSubscriptionUpdated = true;
                cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
            }
        }
         if (serviceToSave.assignedTo) {
             const message = `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`;
             newNotifications.push({
                id: `notif_complete_${serviceToSave.submissionId}`,
                userId: serviceToSave.assignedTo,
                serviceId: serviceToSave.submissionId,
                message,
                timestamp: new Date().toISOString(),
                isRead: false,
                type: 'completed'
            });
        }
        sendCustomerEmailNotification(serviceToSave);
    }

    const updatedSubmissions = isUpdating 
        ? submissions.map(s => s.submissionId === service.submissionId ? serviceToSave : s)
        : [...submissions, serviceToSave];

    setSubmissions(updatedSubmissions);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);

    if(wasSubscriptionUpdated) {
        setUserSubscriptions(finalUserSubscriptions);
    }

    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));

        const targetUser = users.find(u => u.username === serviceToSave.assignedTo);
        const prefs = targetUser?.notificationPreferences || defaultNotificationPrefs;
        if (prefs.enabled.completed) {
            playNotificationAlert(prefs);
            if(targetUser?.pushSubscription) sendPushNotification(targetUser.pushSubscription, "Order Completed", newNotifications[0].message, prefs);
        }
    }

    triggerHapticFeedback('success');
    setView('DASHBOARD');
    setEditingService(null);
  };

