              )}
               {hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) && <NavLink
                icon={<IconSearch />}
                label="Customer History"
                isActive={currentView === 'CUSTOMER_HISTORY'}
                onClick={() => onNavigate('CUSTOMER_HISTORY')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) && <NavLink
                icon={<IconRetention />}
                label="Retention"
                isActive={currentView === 'RETENTION'}
                onClick={() => onNavigate('RETENTION')}
                isMinimized={isMinimized}
              />}
