        }));

        const submissions: Service[] = (flatData.Submissions || []).map((sub: any): Service => {
            let status = sub.status;
            const validStatuses = Object.values(ServiceStatus);

            if (status === "Submitted") status = ServiceStatus.Completed;
            else if (status === "Order Created") status = ServiceStatus.Queued;
            if (!status || !validStatuses.includes(status as ServiceStatus)) status = ServiceStatus.Queued;

            let dynamicAddons = [];
            try {
                if (sub.dynamicAddons && typeof sub.dynamicAddons === 'string') dynamicAddons = JSON.parse(sub.dynamicAddons);
